.stopper-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  cursor: pointer;
}
.stopper-svg {
  width: 30px;
  height: 40px;
  transition: transform 0.2s, filter 0.2s;
  filter: drop-shadow(0 1px 4px rgba(0,0,0,0.06));
}
.stopper-svg.hovered {
  transform: scale(1.1);
  filter: drop-shadow(0 3px 8px rgba(0,0,0,0.1));
}

